-- Generated by scripts/build_osi.py from the ontology. Do not edit.
CREATE OR REPLACE SEMANTIC VIEW GLP.SEMANTIC.JAPAN_MARKET
  TABLES (
    national_value AS GLP.SEMANTIC.SV_JP_NATIONAL_VALUE PRIMARY KEY (PRODUCT_ID, CARE_SETTING_ID, CLASS_ID)
      COMMENT = 'National totals (総計) per product and care setting, FY2024. Use it unless the question is by prefecture, month or sex and age. Products whose whole row NDB masked are left out. One row per product and therapeutic class of any of its substances, including all broader classes (skos:broader*): filter or group by one class, or use the *_all metrics, which count each product once (the top class).',
    prefecture_value AS GLP.SEMANTIC.SV_JP_PREFECTURE_VALUE PRIMARY KEY (PRODUCT_ID, CARE_SETTING_ID, PREFECTURE_CODE, CLASS_ID)
      COMMENT = 'Values by prefecture of the issuing medical institution. Masked cells are left out, so sums are lower bounds. One row per product and therapeutic class of any of its substances, including all broader classes (skos:broader*): filter or group by one class, or use the *_all metrics, which count each product once (the top class).',
    month_value AS GLP.SEMANTIC.SV_JP_MONTH_VALUE PRIMARY KEY (PRODUCT_ID, CARE_SETTING_ID, MONTH, CLASS_ID)
      COMMENT = 'Values by month of care. Masked cells are left out, so sums are lower bounds. One row per product and therapeutic class of any of its substances, including all broader classes (skos:broader*): filter or group by one class, or use the *_all metrics, which count each product once (the top class).',
    sex_age_value AS GLP.SEMANTIC.SV_JP_SEX_AGE_VALUE PRIMARY KEY (PRODUCT_ID, CARE_SETTING_ID, SEX_AGE_CODE, CLASS_ID)
      COMMENT = 'Values by sex and five-year age band of the patient. Masked cells are left out, so sums are lower bounds. One row per product and therapeutic class of any of its substances, including all broader classes (skos:broader*): filter or group by one class, or use the *_all metrics, which count each product once (the top class).',
    product AS GLP.SEMANTIC.SV_JP_PRODUCT PRIMARY KEY (PRODUCT_ID)
      WITH SYNONYMS = ('medicinal product', '药品')
      COMMENT = 'A drug product as named in claims data: in Part D (CMS Brnd_Name, e.g. Jardiance; unbranded generics appear under their generic name), or in NDB Open Data, where each strength is its own product with a receipt code and a YJ code (e.g. ジャディアンス錠10mg). NDB Open Data products at strength level.',
    therapeutic_class AS GLP.SEMANTIC.SV_JP_THERAPEUTIC_CLASS PRIMARY KEY (CLASS_ID)
      COMMENT = 'A concept in the therapeutic class scheme (e.g. SGLT2 inhibitors). The hierarchy itself is maintained as a SKOS concept scheme, not as OWL subclasses.',
    jp_drug_class AS GLP.SEMANTIC.SV_JP_JP_DRUG_CLASS PRIMARY KEY (JP_CLASS_CODE)
      COMMENT = 'A three-digit therapeutic category of the Japan Standard Commodity Classification (薬効分類), as used by the NHI price list and NDB Open Data, e.g. 396 糖尿病用剤. Joined as the product''s category. Most GLP-1 drugs are filed under 249, not 396.',
    prefecture AS GLP.SEMANTIC.SV_JP_PREFECTURE PRIMARY KEY (PREFECTURE_CODE)
      COMMENT = 'One of Japan''s 47 prefectures, identified by its JIS X 0401 code (01-47).',
    care_setting AS GLP.SEMANTIC.SV_JP_CARE_SETTING PRIMARY KEY (CARE_SETTING_ID)
      COMMENT = 'Where a drug was prescribed and dispensed: outpatient with a prescription filled at a community pharmacy (院外), outpatient dispensed in the clinic or hospital (院内), or inpatient (入院).',
    sex_age_group AS GLP.SEMANTIC.SV_JP_SEX_AGE_GROUP PRIMARY KEY (SEX_AGE_CODE)
      COMMENT = 'A sex combined with a five-year age band (0-4 ... 95-99, 100+), as NDB Open Data reports them.'
  )
  RELATIONSHIPS (
    national_value_to_product AS national_value (PRODUCT_ID) REFERENCES product (PRODUCT_ID),
    national_value_to_therapeutic_class AS national_value (CLASS_ID) REFERENCES therapeutic_class (CLASS_ID),
    national_value_to_care_setting AS national_value (CARE_SETTING_ID) REFERENCES care_setting (CARE_SETTING_ID),
    prefecture_value_to_product AS prefecture_value (PRODUCT_ID) REFERENCES product (PRODUCT_ID),
    prefecture_value_to_therapeutic_class AS prefecture_value (CLASS_ID) REFERENCES therapeutic_class (CLASS_ID),
    prefecture_value_to_care_setting AS prefecture_value (CARE_SETTING_ID) REFERENCES care_setting (CARE_SETTING_ID),
    month_value_to_product AS month_value (PRODUCT_ID) REFERENCES product (PRODUCT_ID),
    month_value_to_therapeutic_class AS month_value (CLASS_ID) REFERENCES therapeutic_class (CLASS_ID),
    month_value_to_care_setting AS month_value (CARE_SETTING_ID) REFERENCES care_setting (CARE_SETTING_ID),
    sex_age_value_to_product AS sex_age_value (PRODUCT_ID) REFERENCES product (PRODUCT_ID),
    sex_age_value_to_therapeutic_class AS sex_age_value (CLASS_ID) REFERENCES therapeutic_class (CLASS_ID),
    sex_age_value_to_care_setting AS sex_age_value (CARE_SETTING_ID) REFERENCES care_setting (CARE_SETTING_ID),
    prefecture_value_to_prefecture AS prefecture_value (PREFECTURE_CODE) REFERENCES prefecture (PREFECTURE_CODE),
    sex_age_value_to_sex_age_group AS sex_age_value (SEX_AGE_CODE) REFERENCES sex_age_group (SEX_AGE_CODE),
    product_to_jp_drug_class AS product (JP_CLASS_CODE) REFERENCES jp_drug_class (JP_CLASS_CODE)
  )
  FACTS (
    national_value.quantity AS national_value.QUANTITY
      WITH SYNONYMS = ('total quantity', '総計（処方数量）')
      COMMENT = 'The national total of the row (総計). Unmasked unless the whole product is below the masking threshold in that care setting; then the slice carries sdmx-attribute:confStatus instead.',
    national_value.class_total_value_yen AS national_value.CLASS_TOTAL_VALUE_YEN
      COMMENT = 'The national value of the row''s class (all products, all care settings), repeated on every row: the denominator of class_market_share.',
    national_value.market_total_value_yen AS national_value.MARKET_TOTAL_VALUE_YEN
      COMMENT = 'The national value of all diabetes drugs, repeated on every row: the denominator of market_share.',
    national_value.value_yen AS national_value.VALUE_YEN
      COMMENT = 'Quantity times the NHI price, in yen.',
    prefecture_value.quantity AS prefecture_value.QUANTITY
      WITH SYNONYMS = ('処方数量')
      COMMENT = 'Dispensed quantity in the product''s dispensing unit. Absent when NDB masked the cell; the observation then carries sdmx-attribute:confStatus sdmx-code:confStatus-C.',
    prefecture_value.value_yen AS prefecture_value.VALUE_YEN
      COMMENT = 'Quantity times the NHI price, in yen.',
    month_value.quantity AS month_value.QUANTITY
      COMMENT = 'Dispensed quantity in the product''s dispensing unit. Absent when NDB masked the cell; the observation then carries sdmx-attribute:confStatus sdmx-code:confStatus-C.',
    month_value.generic_quantity AS month_value.GENERIC_QUANTITY
      COMMENT = 'Quantity of products flagged generic (reimbursement definition), else 0. Comparable with quantity within one class only.',
    month_value.value_yen AS month_value.VALUE_YEN
      COMMENT = 'Quantity times the NHI price, in yen.',
    sex_age_value.quantity AS sex_age_value.QUANTITY
      COMMENT = 'Dispensed quantity in the product''s dispensing unit. Absent when NDB masked the cell; the observation then carries sdmx-attribute:confStatus sdmx-code:confStatus-C.',
    sex_age_value.value_yen_age75plus AS sex_age_value.VALUE_YEN_AGE75PLUS
      COMMENT = 'value_yen of patients aged 75 and over (後期高齢者), else 0.',
    sex_age_value.value_yen_female AS sex_age_value.VALUE_YEN_FEMALE
      COMMENT = 'value_yen of female patients, else 0.',
    sex_age_value.value_yen AS sex_age_value.VALUE_YEN
      COMMENT = 'Quantity times the NHI price, in yen.',
    product.nhi_price AS product.NHI_PRICE
      WITH SYNONYMS = ('NHI price (JPY per unit)', '薬価')
      COMMENT = 'Reimbursement price in yen per dispensing unit (tablet, pen, ...), as printed in NDB Open Data.'
  )
  DIMENSIONS (
    national_value.product_id AS national_value.PRODUCT_ID
      COMMENT = 'Product key (receipt code).',
    national_value.care_setting_id AS national_value.CARE_SETTING_ID
      COMMENT = 'outpatient-external (community pharmacy, 院外), outpatient-internal (dispensed in-house, 院内) or inpatient (入院).',
    national_value.class_id AS national_value.CLASS_ID
      COMMENT = 'Therapeutic class key.',
    prefecture_value.product_id AS prefecture_value.PRODUCT_ID
      COMMENT = 'Product key (receipt code).',
    prefecture_value.care_setting_id AS prefecture_value.CARE_SETTING_ID
      COMMENT = 'outpatient-external (community pharmacy, 院外), outpatient-internal (dispensed in-house, 院内) or inpatient (入院).',
    prefecture_value.class_id AS prefecture_value.CLASS_ID
      COMMENT = 'Therapeutic class key.',
    prefecture_value.prefecture_code AS prefecture_value.PREFECTURE_CODE
      COMMENT = 'JIS X 0401 code, 01-47.',
    month_value.product_id AS month_value.PRODUCT_ID
      COMMENT = 'Product key (receipt code).',
    month_value.care_setting_id AS month_value.CARE_SETTING_ID
      COMMENT = 'outpatient-external (community pharmacy, 院外), outpatient-internal (dispensed in-house, 院内) or inpatient (入院).',
    month_value.class_id AS month_value.CLASS_ID
      COMMENT = 'Therapeutic class key.',
    month_value.month AS month_value.MONTH
      WITH SYNONYMS = ('month of care', '診療月')
      COMMENT = 'Month of care. First day of the month of care, 2024-04 to 2025-03.',
    sex_age_value.product_id AS sex_age_value.PRODUCT_ID
      COMMENT = 'Product key (receipt code).',
    sex_age_value.care_setting_id AS sex_age_value.CARE_SETTING_ID
      COMMENT = 'outpatient-external (community pharmacy, 院外), outpatient-internal (dispensed in-house, 院内) or inpatient (入院).',
    sex_age_value.class_id AS sex_age_value.CLASS_ID
      COMMENT = 'Therapeutic class key.',
    sex_age_value.sex_age_code AS sex_age_value.SEX_AGE_CODE
      COMMENT = 'F or M with the band''s minimum age, e.g. F75.',
    product.product_id AS product.PRODUCT_ID
      WITH SYNONYMS = ('receipt code', 'レセプト電算処理システム用コード')
      COMMENT = 'The 9-digit drug code of the claims (receipt) processing system (医薬品コード), the key of NDB Open Data.',
    product.product_name_ja AS product.PRODUCT_NAME_JA
      WITH SYNONYMS = ('医薬品')
      COMMENT = 'Medicinal product name in Japanese. As printed in NDB, with full-width characters, e.g. ジャディアンス錠１０ｍｇ.',
    product.product_name AS product.PRODUCT_NAME
      COMMENT = 'The same name with half-width characters, e.g. ジャディアンス錠10mg.',
    product.yj_code AS product.YJ_CODE
      WITH SYNONYMS = ('薬価基準収載医薬品コード')
      COMMENT = 'The 12-character NHI price list code (薬価基準収載医薬品コード). Characters 1-4 are the therapeutic category, 1-7 the ingredient, 8 the dosage form.',
    product.active_substances AS product.ACTIVE_SUBSTANCES
      WITH SYNONYMS = ('substance')
      COMMENT = 'Substance name in English. Active substances in English, joined with '' + '' for combination products.',
    product.active_substances_ja AS product.ACTIVE_SUBSTANCES_JA
      WITH SYNONYMS = ('有効成分')
      COMMENT = 'Substance name in Japanese. Active substances in Japanese, joined with ''・''.',
    product.dispensing_unit AS product.DISPENSING_UNIT
      WITH SYNONYMS = ('単位')
      COMMENT = 'The unit in which quantities are counted (錠 tablet, キット kit, 筒 cartridge ...). Quantities in different units cannot be added.',
    product.route AS product.ROUTE
      WITH SYNONYMS = ('route of administration', '投与経路')
      COMMENT = '"oral" or "injection": the NDB table family (内服 / 注射) the product is reported in. Masking thresholds differ: 1,000 for oral, 400 for injection tables.',
    product.is_generic AS product.IS_GENERIC
      WITH SYNONYMS = ('後発品')
      COMMENT = 'Generic (後発医薬品) according to NDB Open Data''s 後発品区分; biosimilars count as generics. Generics priced like their originator (most metformin ''MT'' generics) are not flagged.',
    product.is_originator AS product.IS_ORIGINATOR
      WITH SYNONYMS = ('先発品')
      COMMENT = 'Flagged 先発品 (originator) in the NHI price list. Neither generic nor originator: older products that predate the distinction and unified-name listings.',
    product.is_combination AS product.IS_COMBINATION
      WITH SYNONYMS = ('is combination product', '配合剤', '复方制剂')
      COMMENT = 'Is combination product.',
    product.is_sglt2_product AS product.IS_SGLT2_PRODUCT
      WITH SYNONYMS = ('SGLT2 inhibitor product', 'SGLT2阻害薬製剤', 'SGLT2抑制剂产品')
      COMMENT = 'A medicinal product containing a substance in the SGLT2 inhibitor class, alone or in combination.',
    product.is_glp1_product AS product.IS_GLP1_PRODUCT
      WITH SYNONYMS = ('GLP-1 receptor agonist product', 'GLP-1受容体作動薬製剤', 'GLP-1受体激动剂产品')
      COMMENT = 'A medicinal product containing a substance in the GLP-1 receptor agonist class (including dual GIP/GLP-1 agonists), alone or in combination, whatever its Japanese therapeutic category (249 or 396).',
    product.marketing_authorization_holder AS product.MARKETING_AUTHORIZATION_HOLDER
      WITH SYNONYMS = ('manufactured by')
      COMMENT = 'Manufactured by. Japanese marketing authorization holder in English; NULL for unified-name generics.',
    product.marketing_authorization_holder_ja AS product.MARKETING_AUTHORIZATION_HOLDER_JA
      COMMENT = 'Japanese marketing authorization holder in Japanese, e.g. 日本ベーリンガーインゲルハイム.',
    product.company AS product.COMPANY
      WITH SYNONYMS = ('part of corporate group')
      COMMENT = 'Links a national company (e.g. the Japanese marketing authorization holder 日本ベーリンガーインゲルハイム) to its corporate group as identified by GLEIF. For market shares by company: the corporate group (GLEIF ultimate parent, the same company as in the US data) where known, else the marketing authorization holder. Values: VIATRIS INC. (also: Viatris Healthcare G.K., ヴィアトリス・ヘルスケア, Mylan Pharmaceuticals Inc.); MERCK & CO., INC. (also: MSD K.K., ＭＳＤ, Merck Sharp & Dohme LLC); C.H. Boehringer Sohn AG & Co. KG (also: Nippon Boehringer Ingelheim Co., Ltd., 日本ベーリンガーインゲルハイム, Boehringer Ingelheim Pharmaceuticals, Inc.); NOVO NORDISK A/S (also: Novo Nordisk Pharma Ltd., ノボ ノルディスク ファーマ, Novo Nordisk Inc.); SANOFI (also: Sanofi K.K., サノフィ, Sanofi-Aventis U.S. LLC, Sanofi US Services Inc.); ELI LILLY AND COMPANY (also: Eli Lilly Japan K.K., 日本イーライリリー); ASTRAZENECA PLC (also: AstraZeneca K.K., アストラゼネカ, AstraZeneca AB); otherwise the marketing authorization holder''s own name.',
    product.company_ja AS product.COMPANY_JA
      COMMENT = 'The company in Japanese: the corporate group where known, else the holder. Values: ヴィアトリス (also: ヴィアトリス・ヘルスケア); MSD (also: ＭＳＤ); ベーリンガーインゲルハイム (also: 日本ベーリンガーインゲルハイム); ノボノルディスク (also: ノボ ノルディスク ファーマ); サノフィ (also: ); イーライリリー・アンド・カンパニー (also: 日本イーライリリー); アストラゼネカ (also: ); otherwise the marketing authorization holder''s own name.',
    therapeutic_class.class_id AS therapeutic_class.CLASS_ID
      COMMENT = 'Class key, e.g. SGLT2Inhibitor.',
    therapeutic_class.class_name AS therapeutic_class.CLASS_NAME
      WITH SYNONYMS = ('therapeutic class')
      COMMENT = 'Therapeutic class name in English. Values: Alpha glucosidase inhibitors; Biguanides; Blood glucose lowering drugs, excl. insulins; Dipeptidyl peptidase 4 (DPP-4) inhibitors; Drugs used in diabetes; Glimins; Glinides; Glucagon-like peptide-1 (GLP-1) analogues; Glucose-dependent Insulinotropic Polypeptide Receptor Agonists; Insulins and analogues; Insulins and analogues for injection, fast-acting; Insulins and analogues for injection, intermediate- or long-acting combined with fast-acting; Insulins and analogues for injection, intermediate-acting; Insulins and analogues for injection, long-acting; Sodium-glucose co-transporter 2 (SGLT2) inhibitors; Sulfonylureas; Thiazolidinediones.',
    therapeutic_class.class_name_ja AS therapeutic_class.CLASS_NAME_JA
      WITH SYNONYMS = ('薬効群', 'ATC分類')
      COMMENT = 'Therapeutic class name in Japanese. Values: DPP-4阻害薬; GLP-1受容体作動薬; SGLT2阻害薬; α-グルコシダーゼ阻害薬; インスリン製剤; グリミン系薬; スルホニルウレア薬; チアゾリジン薬; ビグアナイド薬; 中間型インスリン; 持効型溶解インスリン; 持続性GIP/GLP-1受容体作動薬; 混合型インスリン; 糖尿病治療薬; 血糖降下薬（インスリンを除く）; 速効型インスリン分泌促進薬; 速効型・超速効型インスリン.',
    therapeutic_class.class_name_zh AS therapeutic_class.CLASS_NAME_ZH
      WITH SYNONYMS = ('治疗类别')
      COMMENT = 'Therapeutic class name in Chinese. Values: DPP-4抑制剂; GIP/GLP-1双受体激动剂; GLP-1受体激动剂; SGLT2抑制剂; α-葡萄糖苷酶抑制剂; 中效胰岛素; 双胍类药物; 噻唑烷二酮类药物; 格列奈类药物; 格列明类药物; 磺酰脲类药物; 糖尿病治疗药物; 胰岛素及其类似物; 速效胰岛素; 长效胰岛素; 降血糖药（不含胰岛素）; 预混胰岛素.',
    therapeutic_class.atc_code AS therapeutic_class.ATC_CODE
      COMMENT = 'ATC code of the class, e.g. A10BK. Glinides and imeglimin have none.',
    therapeutic_class.class_depth AS therapeutic_class.CLASS_DEPTH
      COMMENT = 'Level in the class tree (skos:broader*): 1 drugs used in diabetes, 2 insulins or blood glucose lowering drugs, 3 drug classes such as SGLT2 inhibitors, 4 narrower classes such as dual GIP/GLP-1 agonists, which also count in their broader class.',
    therapeutic_class.is_drug_class AS therapeutic_class.IS_DRUG_CLASS
      COMMENT = 'TRUE for the drug classes (SGLT2 inhibitors, GLP-1 receptor agonists, DPP-4 inhibitors, biguanides, long-acting insulins, ...): use it whenever a question says ''by drug class'' or ''by class'', so that broader and narrower classes are not listed next to them.',
    jp_drug_class.jp_class_code AS jp_drug_class.JP_CLASS_CODE
      COMMENT = 'Three-digit code, e.g. 396.',
    jp_drug_class.jp_class_name AS jp_drug_class.JP_CLASS_NAME
      WITH SYNONYMS = ('Japanese therapeutic category')
      COMMENT = 'Japanese therapeutic category name in English.',
    jp_drug_class.jp_class_name_ja AS jp_drug_class.JP_CLASS_NAME_JA
      WITH SYNONYMS = ('薬効分類')
      COMMENT = 'Japanese therapeutic category name in Japanese. Values: その他のホルモン剤（抗ホルモン剤を含む。）; 糖尿病用剤.',
    jp_drug_class.jp_class_name_zh AS jp_drug_class.JP_CLASS_NAME_ZH
      WITH SYNONYMS = ('日本药效分类')
      COMMENT = 'Japanese therapeutic category name in Chinese.',
    prefecture.prefecture_code AS prefecture.PREFECTURE_CODE
      COMMENT = 'JIS X 0401 code, 01-47.',
    prefecture.prefecture_name AS prefecture.PREFECTURE_NAME
      WITH SYNONYMS = ('prefecture')
      COMMENT = 'Prefecture name in English.',
    prefecture.prefecture_name_ja AS prefecture.PREFECTURE_NAME_JA
      WITH SYNONYMS = ('都道府県')
      COMMENT = 'Prefecture name in Japanese. Values: 三重県; 京都府; 佐賀県; 兵庫県; 北海道; 千葉県; 和歌山県; 埼玉県; 大分県; 大阪府; 奈良県; 宮城県; 宮崎県; 富山県; 山口県; 山形県; 山梨県; 岐阜県; 岡山県; 岩手県; 島根県; 広島県; 徳島県; 愛媛県; 愛知県; 新潟県; 東京都; 栃木県; 沖縄県; 滋賀県; 熊本県; 石川県; 神奈川県; 福井県; 福岡県; 福島県; 秋田県; 群馬県; 茨城県; 長崎県; 長野県; 青森県; 静岡県; 香川県; 高知県; 鳥取県; 鹿児島県.',
    prefecture.prefecture_name_zh AS prefecture.PREFECTURE_NAME_ZH
      WITH SYNONYMS = ('都道府县')
      COMMENT = 'Prefecture name in Chinese.',
    care_setting.care_setting_id AS care_setting.CARE_SETTING_ID
      COMMENT = 'Care setting key.',
    care_setting.care_setting_name AS care_setting.CARE_SETTING_NAME
      WITH SYNONYMS = ('care setting')
      COMMENT = 'Care setting name in English. Values: inpatient; outpatient; outpatient, community pharmacy; outpatient, dispensed in-house.',
    care_setting.care_setting_name_ja AS care_setting.CARE_SETTING_NAME_JA
      WITH SYNONYMS = ('診療区分')
      COMMENT = 'Care setting name in Japanese. Values: 入院; 外来; 外来（院内）; 外来（院外）.',
    care_setting.care_setting_name_zh AS care_setting.CARE_SETTING_NAME_ZH
      WITH SYNONYMS = ('诊疗类别')
      COMMENT = 'Care setting name in Chinese.',
    sex_age_group.sex_age_code AS sex_age_group.SEX_AGE_CODE
      COMMENT = 'F or M with the band''s minimum age, e.g. F75.',
    sex_age_group.sex_age_name AS sex_age_group.SEX_AGE_NAME
      WITH SYNONYMS = ('sex and age band')
      COMMENT = 'Sex and age band name in English.',
    sex_age_group.sex_age_name_ja AS sex_age_group.SEX_AGE_NAME_JA
      WITH SYNONYMS = ('性・年齢階級')
      COMMENT = 'Sex and age band name in Japanese.',
    sex_age_group.sex_age_name_zh AS sex_age_group.SEX_AGE_NAME_ZH
      WITH SYNONYMS = ('性别年龄组')
      COMMENT = 'Sex and age band name in Chinese.',
    sex_age_group.sex AS sex_age_group.SEX
      COMMENT = 'F (female) or M (male).',
    sex_age_group.min_age AS sex_age_group.MIN_AGE
      WITH SYNONYMS = ('minimum age')
      COMMENT = 'Lower bound of the age band in years (65 for 65-69).'
  )
  METRICS (
    total_value_yen AS SUM(CASE WHEN national_value.class_id = 'DrugsUsedInDiabetes' THEN national_value.value_yen END)
      COMMENT = 'Value in yen of all drugs used in diabetes, each product counted once (national totals).',
    class_value_yen AS SUM(national_value.value_yen)
      COMMENT = 'Value in yen of the products in a therapeutic class (including narrower classes), national totals. Filter or group by one class; a combination product counts in each of its classes.',
    class_market_share AS SUM(national_value.value_yen) / NULLIF(MAX(national_value.class_total_value_yen), 0)
      COMMENT = 'Share (0 to 1) of the class''s national value, for one class at a time. Grouped or filtered by product.company it is the company''s market share in the class: the denominator stays the whole class whatever the filter on products or companies (it covers all care settings).',
    market_share AS SUM(national_value.value_yen) / NULLIF(MAX(national_value.market_total_value_yen), 0)
      COMMENT = 'Share (0 to 1) of the national value of all drugs used in diabetes, whatever the filter on classes, products or companies (it covers all care settings). By class: a class''s share of the market.',
    product_count AS COUNT(DISTINCT product.product_id)
      COMMENT = 'Number of distinct products (strength level).',
    prefecture_value_yen_all AS SUM(CASE WHEN prefecture_value.class_id = 'DrugsUsedInDiabetes' THEN prefecture_value.value_yen END)
      COMMENT = 'Value in yen of all drugs used in diabetes by prefecture, each product counted once.',
    prefecture_class_value_yen AS SUM(prefecture_value.value_yen)
      COMMENT = 'Value in yen of a therapeutic class by prefecture. Filter or group by one class.',
    prefecture_sglt2_value_share AS SUM(CASE WHEN prefecture_value.class_id = 'SGLT2Inhibitor' THEN prefecture_value.value_yen END) / NULLIF(SUM(CASE WHEN prefecture_value.class_id = 'DrugsUsedInDiabetes' THEN prefecture_value.value_yen END), 0)
      COMMENT = 'Share (0 to 1) of Sodium-glucose co-transporter 2 (SGLT2) inhibitors in the value of all drugs used in diabetes (from the definition of dm:SGLT2Product: products with an SGLT2 inhibitor, alone or in combination).',
    month_value_yen_all AS SUM(CASE WHEN month_value.class_id = 'DrugsUsedInDiabetes' THEN month_value.value_yen END)
      COMMENT = 'Value in yen of all drugs used in diabetes by month, each product counted once.',
    month_class_value_yen AS SUM(month_value.value_yen)
      COMMENT = 'Value in yen of a therapeutic class by month. Filter or group by one class.',
    month_generic_quantity_share AS SUM(month_value.generic_quantity) / NULLIF(SUM(month_value.quantity), 0)
      COMMENT = 'Generic share (0 to 1) of the dispensed quantity. Meaningful within one class only; group or filter by class and month.',
    age_value_yen_all AS SUM(CASE WHEN sex_age_value.class_id = 'DrugsUsedInDiabetes' THEN sex_age_value.value_yen END)
      COMMENT = 'Value in yen of all drugs used in diabetes by sex and age band, each product counted once.',
    age_class_value_yen AS SUM(sex_age_value.value_yen)
      COMMENT = 'Value in yen of a therapeutic class by sex and age band. Filter or group by one class.',
    age_75plus_value_share AS SUM(sex_age_value.value_yen_age75plus) / NULLIF(SUM(sex_age_value.value_yen), 0)
      COMMENT = 'Share (0 to 1) of the value dispensed to patients aged 75 and over (後期高齢者).',
    female_value_share AS SUM(sex_age_value.value_yen_female) / NULLIF(SUM(sex_age_value.value_yen), 0)
      COMMENT = 'Share (0 to 1) of the value dispensed to female patients.'
  )
  COMMENT = 'Diabetes drugs dispensed in Japan, generated from the diabetes-market ontology 0.5.2. NDB Open Data, 11th release: FY2024 (April 2024 - March 2025), all of Japan, all ages. Quantities are dispensed tablets, pens or kits, not patients or prescriptions, and cannot be added across products; values are quantity times the NHI price (price list of 2026-09-02), in yen. Cells below 1,000 (oral) or 400 (injection) are masked. The prefecture is where the claim was issued. No prescribers or specialties exist for Japan.'
  AI_SQL_GENERATION 'Answer in yen (value_yen metrics), never by adding quantities across products. The four fact datasets are four breakdowns of the same national figures: never combine them; use national_value unless the question is by prefecture, month, or sex and age. Every fact row is one product in one therapeutic class, broader classes included: for all diabetes drugs use the *_all metrics, which count each product once (they handle the top class internally: never filter class_id yourself to get all drugs); for a class, filter or group by one class. ''By drug class'' means therapeutic_class.is_drug_class = TRUE. A class''s share of the market: market_share by class. A company''s market share in a class: class_market_share with product.company and that class (never divide by the company''s own total). ''Single-ingredient'' means NOT product.is_combination. Prefecture, month and age figures are lower bounds (masked cells). Names exist in English, Japanese (*_ja) and Chinese (*_zh): answer with the names in the language of the question.'
  AI_VERIFIED_QUERIES (
    jp_class_share_yen AS (
      QUESTION 'What share of Japan''s diabetes drug value does each drug class have, for single-ingredient products?'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION TRUE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.JAPAN_MARKET DIMENSIONS therapeutic_class.class_name METRICS class_value_yen, market_share WHERE therapeutic_class.class_id IN (''Insulin'', ''Biguanide'', ''Sulfonylurea'', ''Thiazolidinedione'', ''DPP4Inhibitor'', ''AlphaGlucosidaseInhibitor'', ''Glinide'', ''Glimin'', ''SGLT2Inhibitor'', ''GLP1ReceptorAgonist'') AND NOT product.is_combination) ORDER BY class_value_yen DESC'
    ),
    jp_company_share_sglt2_dpp4 AS (
      QUESTION 'Which companies lead the SGLT2 inhibitor and DPP-4 inhibitor markets in Japan by value?'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION TRUE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.JAPAN_MARKET DIMENSIONS therapeutic_class.class_name, product.company METRICS class_value_yen, class_market_share WHERE therapeutic_class.class_id IN (''SGLT2Inhibitor'', ''DPP4Inhibitor'')) ORDER BY class_name, class_value_yen DESC'
    ),
    jp_age_profile_by_class AS (
      QUESTION 'What share of each drug class''s value goes to patients aged 75 and over, and to women?'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION FALSE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.JAPAN_MARKET DIMENSIONS therapeutic_class.class_name METRICS age_class_value_yen, age_75plus_value_share, female_value_share WHERE therapeutic_class.class_id IN (''Insulin'', ''Biguanide'', ''Sulfonylurea'', ''Thiazolidinedione'', ''DPP4Inhibitor'', ''AlphaGlucosidaseInhibitor'', ''Glinide'', ''Glimin'', ''SGLT2Inhibitor'', ''GLP1ReceptorAgonist'')) ORDER BY age_75plus_value_share DESC'
    ),
    jp_generic_share_by_month AS (
      QUESTION '長期収載品の選定療養が始まった2024年10月の前後で、院外処方の後発品の割合は薬効群ごとに毎月どう変わった？'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION FALSE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.JAPAN_MARKET DIMENSIONS therapeutic_class.class_name, month_value.month METRICS month_generic_quantity_share WHERE month_value.care_setting_id = ''outpatient-external'' AND NOT product.is_combination AND therapeutic_class.class_id IN (''Biguanide'', ''Sulfonylurea'', ''Thiazolidinedione'', ''DPP4Inhibitor'', ''AlphaGlucosidaseInhibitor'', ''Glinide'')) ORDER BY class_name, month'
    ),
    jp_glp1_monthly_uptake AS (
      QUESTION 'How did the monthly value of each GLP-1 receptor agonist substance develop in Japan?'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION FALSE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.JAPAN_MARKET DIMENSIONS month_value.month, product.active_substances METRICS month_class_value_yen WHERE therapeutic_class.class_id = ''GLP1ReceptorAgonist'' AND NOT product.is_combination) ORDER BY month, month_class_value_yen DESC'
    ),
    jp_sglt2_share_by_prefecture AS (
      QUESTION '都道府県別のSGLT2阻害薬のシェアは？'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION TRUE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.JAPAN_MARKET DIMENSIONS prefecture.prefecture_name_ja METRICS prefecture_sglt2_value_share, prefecture_value_yen_all) ORDER BY prefecture_sglt2_value_share DESC'
    ),
    jp_glp1_products_by_category AS (
      QUESTION 'GLP-1受容体作動薬製剤は薬効分類ごとにいくつある？'
      VERIFIED_AT 1793404800
      ONBOARDING_QUESTION FALSE
      SQL 'SELECT * FROM SEMANTIC_VIEW(GLP.SEMANTIC.JAPAN_MARKET DIMENSIONS jp_drug_class.jp_class_name_ja METRICS product_count WHERE product.is_glp1_product) ORDER BY product_count DESC'
    )
  );
